"""Rebrand Indore Tutorials -> Infinite360 Tech Academy.

New model defaults, plus a data pass over the rows already in the database: brand name,
contact email/phone, the gold theme color (only where it was never customised) and the
brand artwork (logo, favicon, login/signup images and the seven brand banners), copied
from base/static/img/brand/. Safe to re-run; nothing is deleted except replaced brand files.
"""
from pathlib import Path

from django.conf import settings
from django.core.cache import cache
from django.core.files import File
from django.db import migrations, models

BRAND_DIR = Path(settings.BASE_DIR) / "base" / "static" / "img" / "brand"

OLD_COLOR, NEW_COLOR = "#fcbc00", "#2459E0"
TEXT_REPLACEMENTS = [
    ("Indore Tutorials", "Infinite360"),
    ("indoretutorial1857@gmail.com", "businessconsulting@gmail.com"),
    ("+91 74896 99909", "+91 82968 93895"),
    ("7489699909", "8296893895"),
]
BRAND_BANNERS = {  # title -> artwork number (banner-<n>-desktop/mobile.webp)
    "Learn Smarter, Score Higher": 1,
    "Boost Your Score with Smart Tests": 2,
    "Knowledge That Costs Nothing": 3,
    "Learn Anytime, Anywhere": 4,
    "Free Test Series for 3 Months": 5,
    "Ace Your Board Exams": 6,
    "Crack Your Dream Exam": 7,
}
CACHE_KEYS = (
    "site-theme-settings-v1", "site-navbar-settings-v3",
    "site-footer-settings-v3", "site-auth-page-settings-v1",
)


def rebrand_text(value):
    for old, new in TEXT_REPLACEMENTS:
        value = value.replace(old, new)
    return value


def update_text(obj, *fields):
    changed = False
    for field in fields:
        value = getattr(obj, field) or ""
        new = rebrand_text(value)
        if new != value:
            setattr(obj, field, new)
            changed = True
    return changed


def attach(instance, field_name, filename):
    """Swap the file in an image field for base/static/img/brand/<filename>."""
    source = BRAND_DIR / filename
    if not source.exists():
        return False
    field = getattr(instance, field_name)
    if field and field.name:
        try:
            field.storage.delete(field.name)
        except Exception:
            pass
    with open(source, "rb") as fh:
        field.save(filename, File(fh), save=False)
    return True


def apply_rebrand(apps, schema_editor):
    AboutUsSection = apps.get_model("adminpanel", "AboutUsSection")
    AuthPageSettings = apps.get_model("adminpanel", "AuthPageSettings")
    Banner = apps.get_model("adminpanel", "Banner")
    CTASection = apps.get_model("adminpanel", "CTASection")
    ExtraPage = apps.get_model("adminpanel", "ExtraPage")
    FooterSettings = apps.get_model("adminpanel", "FooterSettings")
    NavbarSettings = apps.get_model("adminpanel", "NavbarSettings")
    ThemeSettings = apps.get_model("adminpanel", "ThemeSettings")

    for about in AboutUsSection.objects.all():
        update_text(about, "company_name", "heading", "description", "email", "phone")
        attach(about, "logo", "logo-badge.png")
        about.save()

    for footer in FooterSettings.objects.all():
        update_text(footer, "email", "copyright_text")
        attach(footer, "logo", "logo-horizontal-light.png")
        footer.save()

    for navbar in NavbarSettings.objects.all():
        update_text(navbar, "contact_number")
        if navbar.contact_number == "8296893895":
            navbar.contact_number = "82968 93895"  # shown as-is in the navbar; the link strips spaces
        attach(navbar, "logo", "logo-inline.png")
        attach(navbar, "favicon", "favicon.png")
        navbar.save()

    for page in ExtraPage.objects.all():
        if update_text(page, "title", "content"):
            page.save(update_fields=["title", "content"])

    for auth in AuthPageSettings.objects.all():
        attach(auth, "login_image", "auth-login.webp")
        attach(auth, "signup_image", "auth-signup.webp")
        attach(auth, "login_image_mobile", "auth-login-mobile.webp")
        attach(auth, "signup_image_mobile", "auth-signup-mobile.webp")
        auth.save()

    for banner in Banner.objects.all():
        n = BRAND_BANNERS.get(banner.title)
        if n:
            attach(banner, "image", f"banner-{n}-desktop.webp")
            attach(banner, "mobile_image", f"banner-{n}-mobile.webp")
        update_text(banner, "alt_text")
        banner.save()

    # Recolor only where the old gold default was never changed by an admin.
    for theme in ThemeSettings.objects.all():
        if (theme.primary_color or "").lower() == OLD_COLOR:
            theme.primary_color = NEW_COLOR
            theme.save(update_fields=["primary_color"])
    for cta in CTASection.objects.all():
        if (cta.button_color or "").lower() == OLD_COLOR:
            cta.button_color = NEW_COLOR
            cta.save(update_fields=["button_color"])

    # Historical models skip the custom save() hooks that clear these caches.
    try:
        cache.delete_many(CACHE_KEYS)
    except Exception:
        pass

